using System.Text.RegularExpressions;

namespace BlocksBeyondTheStars.Client.Tests;

/// <summary>
/// The width of a uGUI label without Unity (#3263): the sum of the bundled fonts' glyph advances
/// (<see cref="UiFontAdvances"/>, generated by <c>tools/gen_font_advances.py</c>), each rounded at the font size like
/// Unity's importer does, no kerning. Within ±2 % of Unity's own <c>TextGenerator</c> (see
/// <see cref="UiTextMeasureTests"/>). A character none of the fonts has measures 1 em — the CJK rule.
/// </summary>
internal static class UiTextMeasure
{
    private static readonly Regex Tags = new(@"<[^<>]+>", RegexOptions.Compiled, TimeSpan.FromSeconds(1));

    /// <summary>The one-line width of <paramref name="text"/> at <paramref name="size"/> px (line breaks ignored).</summary>
    public static float Width(string text, int size)
    {
        float width = 0f;
        foreach (int cp in CodePoints(text))
        {
            if (cp == '\n' || cp == '\r')
            {
                continue;
            }

            width += (float)Math.Round(Advance(cp) / 1000.0 * size, MidpointRounding.AwayFromZero);
        }

        return width;
    }

    /// <summary>The widest line of <paramref name="text"/>.</summary>
    public static float WidestLine(string text, int size) => text.Split('\n').Max(line => Width(line, size));

    /// <summary>The visible text of a rich-text label (tags take no room).</summary>
    public static string StripTags(string text) => Tags.Replace(text, string.Empty);

    /// <summary>The advance of a code point in 1/1000 em.</summary>
    public static int Advance(int codePoint)
    {
        int[] runs = UiFontAdvances.Runs;
        int lo = 0, hi = (runs.Length / 3) - 1;
        while (lo <= hi)
        {
            int mid = (lo + hi) / 2;
            int first = runs[mid * 3], last = runs[(mid * 3) + 1];
            if (codePoint < first)
            {
                hi = mid - 1;
            }
            else if (codePoint > last)
            {
                lo = mid + 1;
            }
            else
            {
                return runs[(mid * 3) + 2];
            }
        }

        return 1000;
    }

    private static IEnumerable<int> CodePoints(string text)
    {
        for (int i = 0; i < text.Length; i++)
        {
            if (char.IsHighSurrogate(text[i]) && i + 1 < text.Length && char.IsLowSurrogate(text[i + 1]))
            {
                yield return char.ConvertToUtf32(text[i], text[i + 1]);
                i++;
            }
            else
            {
                yield return text[i];
            }
        }
    }
}
